export function buildMissionHeader(input={}){if(!input.missionId)throw new Error('missionId is required');return Object.freeze({missionId:String(input.missionId),title:String(input.title??'Mission'),status:String(input.status??'draft'),isolationLabel:input.worktreeIsolated?'Worktree isolated':'Main workspace',actions:Object.freeze(input.status==='running'?['pause','stop','more']:['more'])})}
